type Syllabus struct {
	// CreatedAt RFC 3339 creation timestamp.
	CreatedAt time.Time `json:"createdAt"`

	// Description Optional longer description of the syllabus.
	Description *string `json:"description,omitempty"`

	// Id Server-assigned unique identifier.
	Id string `json:"id"`

	// Name Human-readable syllabus name (e.g. "Class V").
	Name string `json:"name"`
}

// Topic A unit of study within a subject. May optionally point at a source and a page range. `order` controls syllabus position; `active` toggles whether the topic is in scope for exams.
type Topic struct {
	// Active Whether the topic is active (in scope for exams).
	Active bool `json:"active"`

	// Id Unique topic identifier (UUID/cuid).
	Id string `json:"id"`

	// Name Human-readable topic name.
	Name string `json:"name"`

	// Order Position of the topic in the subject's syllabus.
	Order int32 `json:"order"`

	// PageEnd Optional last page of the topic within its source. If both pages are present, pageEnd must be >= pageStart.
	PageEnd *int32 `json:"pageEnd,omitempty"`

	// PageStart Optional first page of the topic within its source.
	PageStart *int32 `json:"pageStart,omitempty"`

	// SourceId Optional identifier of the source this topic is drawn from.
	SourceId *string `json:"sourceId,omitempty"`

	// SubjectId Identifier of the owning subject.
	SubjectId string `json:"subjectId"`
}

// TopicMastery A single topic's mastery level for a student.
type TopicMastery struct {
	// Mastery Mastery level as a whole percentage (0–100).
	Mastery int `json:"mastery"`

	// TopicId The topic this mastery is for.
	TopicId string `json:"topicId"`
}

// TopicSuggestion A single suggested syllabus topic derived by the knowledge backend from ingested sources. Topics form a recursive tree via `children`.
type TopicSuggestion struct {
	// Children Optional nested sub-topics (recursive).
	Children *[]TopicSuggestion `json:"children,omitempty"`

	// Name Human-readable topic name.
	Name string `json:"name"`

	// Order Zero-based ordering of this topic among its siblings.
	Order int `json:"order"`

	// PageEnd Optional 1-based end page in the source where this topic ends.
	PageEnd *int `json:"pageEnd,omitempty"`

	// PageStart Optional 1-based start page in the source where this topic begins.
	PageStart *int `json:"pageStart,omitempty"`

	// SourceId Optional id of the ingested Source this topic was derived from (UUID/cuid). Absent when the suggestion is not anchored to a source.
	SourceId *string `json:"sourceId,omitempty"`
}

// TutorInstructions Per-subject configuration that steers the AI tutor's behaviour for a given subject (spec §2.7). Set/edited by a parent via GET/PUT /subjects/{id}/tutor-instructions.
type TutorInstructions struct {
	// CustomInstructions Free-text instructions the parent provides to shape how the tutor explains, questions, and encourages the student for this subject.
	CustomInstructions string `json:"customInstructions"`

	// Difficulty Optional difficulty level the tutor should pitch explanations and follow-up questions at.
	Difficulty *TutorInstructionsDifficulty `json:"difficulty,omitempty"`

	// SubjectId Identifier of the Subject these instructions apply to (UUID/cuid).
	SubjectId string `json:"subjectId"`

	// TargetLanguage Optional language the tutor should respond in (e.g. a BCP 47 tag such as "en" or "es").
	TargetLanguage *string `json:"targetLanguage,omitempty"`

	// Tone Optional desired conversational tone for the tutor (e.g. "encouraging", "socratic", "concise").
	Tone *string `json:"tone,omitempty"`
}

// TutorInstructionsDifficulty Optional difficulty level the tutor should pitch explanations and follow-up questions at.
type TutorInstructionsDifficulty string

// WebAuthnCeremony Free-form WebAuthn ceremony payload (registration/authentication options or the authenticator's response). Opaque — the structure is owned by the WebAuthn libraries, not this contract.
type WebAuthnCeremony map[string]interface{}

